import{_ as a,c as t,o as n,aj as p}from"./chunks/framework.DflVTzjJ.js";const m=JSON.parse('{"title":"第2篇 工程财务","description":"","frontmatter":{"title":"第2篇 工程财务","layout":"doc","order":3},"headers":[],"relativePath":"考试/一级建造师/工程经济/第2篇 工程财务.md","filePath":"考试/一级建造师/工程经济/第2篇 工程财务.md","lastUpdated":0}'),o={name:"考试/一级建造师/工程经济/第2篇 工程财务.md"};function c(e,s,r,l,i,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="第2篇-工程财务" tabindex="-1">第2篇 工程财务 <a class="header-anchor" href="#第2篇-工程财务" aria-label="Permalink to “第2篇 工程财务”">​</a></h1><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1763393378378.jpg" style="zoom:45%;"><h2 id="第6章-财务会计基础" tabindex="-1">第6章 财务会计基础 <a class="header-anchor" href="#第6章-财务会计基础" aria-label="Permalink to “第6章 财务会计基础”">​</a></h2><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1763393430078.jpg" style="zoom:45%;"><h3 id="_6-1-会计要素的组成及计量" tabindex="-1">6.1 会计要素的组成及计量 <a class="header-anchor" href="#_6-1-会计要素的组成及计量" aria-label="Permalink to “6.1 会计要素的组成及计量”">​</a></h3><p><strong>6.1.1 会计要素的组成</strong></p><p>资产=负债+所有者权益</p><p>利润=收入-费用</p><p><span class="font-jcysxh">静态</span>会计要素：<span class="font-jcysxh">资产、负债和所有者权益</span>是反映企业某一<span class="font-jcysxh">时点</span>财务状况的。</p><p><span class="font-jcysxh">动态</span>会计要素：<span class="font-jcysxh">收入、费用和利润</span>是反映企业某一<span class="font-jcysxh">时期</span>经营成果的。</p><p><span class="font-jcysxh">1.资产</span></p><p>指企业<span class="font-jcysxh">过去的交易</span>或事项所形成的，由企业所<span class="font-jcysxh">拥有或控制</span>的，预期会给企业带来经济利益的经济资源。</p><p><strong>• 流动资产</strong></p><p><span class="font-jcysxh">一年内（含）</span>或超过一年的一个营业周期内变现、耗用的资产，主要为<span class="font-jcysxh">交易目的</span>而持有。</p><p><strong>• 非流动资产</strong></p><p><span class="font-jcysxh">超过一年</span>或长于一年的一个营业周期的资产。</p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1763393737764.jpg" style="zoom:45%;"><p><span class="font-jcysxh">2.负债</span></p><p>负债是指企业<span class="font-jcysxh">过去的交易或事项形成</span>的、预期会导致经济利益流出企业的<span class="font-jcysxh">现时义务</span>。</p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1763393808641.jpg" style="zoom:45%;"><p><strong>• 流动负债</strong></p><p>指在<span class="font-jcysxh">一年内</span>或超过一年的<span class="font-jcysxh">一个营业周期内</span>偿还的债务。</p><p><strong>• 非流动负债</strong></p><p>一年以上或超过一年的一个营业周期以上偿还的债务。</p><img src="https://tupian-d290.obs.cn-east-3.myhuaweicloud.com/img/1763393875109.jpg" style="zoom:40%;"><table class="table-marquee"><tbody><tr><td>概念</td><td style="text-align:left;"> • 企业投资者对企业<span class="font-jcysxh">净资产的所有权</span><br> • 所有者权益（净资产）=资产-负债<br> • 公司的所有者权益又称为股东权益</td></tr><tr><td>内容</td><td style="text-align:left;"> • 实收资本：投资人投入的<br> • 其他权益工具<br> • 资本公积<br> • 其他综合收益<br> • 专项储备<br> • 盈余公积<br> • 未分配利润 </td></tr></tbody></table>',26)])])}const y=a(o,[["render",c]]);export{m as __pageData,y as default};
